			var fd = layout.field;
			ctx.fillStyle = fd.color;
			ctx.beginPath();
			ctx.moveTo(fd.from[0] * SIZE, fd.from[1] * SIZE);
			ctx.lineTo(fd.to[0] * SIZE, fd.to[1] * SIZE);
